using Microsoft.EntityFrameworkCore;using POS.Application.Channels;using POS.Domain.Entities;using POS.Infrastructure.Persistence;using Xunit;
namespace POS.Application.Tests;public class BranchChannelTests{[Fact]public async Task Channel_can_have_different_settings_per_branch(){await using var db=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);db.Database.EnsureCreated();var a=new Branch{Id=Guid.NewGuid(),Code="A",NameAr="أ",NameEn="A"};var b=new Branch{Id=Guid.NewGuid(),Code="B",NameAr="ب",NameEn="B"};db.Branches.AddRange(a,b);var service=new ChannelService(db);var channel=await service.CreateAsync(new("QR_CAR","سيارة QR","QR car",null,true),TestContext.Current.CancellationToken);var first=await service.SetAvailabilityAsync(a.Id,channel.Id,new(true,true),TestContext.Current.CancellationToken);var second=await service.SetAvailabilityAsync(b.Id,channel.Id,new(false,false),TestContext.Current.CancellationToken);Assert.True(first.IsEnabled);Assert.True(first.RequiresPrepayment);Assert.False(second.IsEnabled);Assert.False(second.RequiresPrepayment);}}
